import heapq
from itertools import combinations


def _route(data, exact, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    # A state includes every property affecting future feasibility.
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if (node == target and mask == full and
                (used == data["coupons"] if exact else True)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(depart + edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((depart + duration, used + 1))
            for arrival, next_used in options:
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_component_01():
    return lambda data: _route(data, False, 1)


def _build_component_02():
    return lambda data: _route(data, True, 1)


def _build_component_03():
    return lambda data: _route(data, False, 2)


def _build_component_04():
    return lambda data: _route(data, True, 2)


def _build_component_05():
    return lambda data: _route(data, False, 1)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial_constraints = {name: [tuple(bounds)]
                               for name, bounds in data["roots"].items()}
        best_vector = None
        best_chosen = None

        def cyclic(edges):
            state = {}

            def visit(name):
                mark = state.get(name, 0)
                if mark == 1:
                    return True
                if mark == 2:
                    return False
                state[name] = 1
                for child in edges.get(name, ()):
                    if visit(child):
                        return True
                state[name] = 2
                return False

            return any(visit(name) for name in edges if state.get(name, 0) == 0)

        def search(chosen, constraints, edges):
            nonlocal best_vector, best_chosen
            pending = [name for name in constraints if name not in chosen]
            if not pending:
                if cyclic(edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_chosen = dict(chosen)
                return

            name = min(pending)
            ranges = constraints[name]
            rows = []
            for row in packages.get(name, []):
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                rows.append(row)

            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_constraints = {key: list(value) for key, value in constraints.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                next_edges.setdefault(name, [])
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    child = dep["name"]
                    interval = (dep["min"], dep["max"])
                    next_constraints.setdefault(child, []).append(interval)
                    next_edges[name].append(child)
                    if child in next_chosen and not interval[0] <= next_chosen[child] <= interval[1]:
                        valid = False
                        break
                if valid:
                    search(next_chosen, next_constraints, next_edges)

        search({}, initial_constraints, {})
        if best_chosen is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_chosen}
    return solve


def _build_component_08():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        eligible = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for subset in combinations(eligible, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
